// Shared vectors generated by the Python SDK (examples/conformance/build_vectors.py).
// Passing these means Node encodes, hashes and validates exactly like Python.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { canonicalJson, refOf, validate } from "../dist/index.js";

const dir = fileURLToPath(new URL("../../../examples/conformance/", import.meta.url));
const load = (name) => JSON.parse(readFileSync(dir + name, "utf-8"));

for (const [i, v] of load("canonical.json").entries()) {
  test("canonical vector " + i, () => {
    assert.equal(canonicalJson(v.value), v.canonical);
    assert.equal(refOf(v.value), v.ref);
  });
}

for (const v of load("validation.json")) {
  test("validation vector: " + v.name, () => {
    assert.deepEqual(validate(v.trace), v.errors);
  });
}
